query:
-- Verificar se existem equipamentos cadastrados com essas tags
SELECT id, codigoTag, nomeDoEquipamento, excluidoCusto FROM equipamentos 
WHERE codigoTag IN ('QMD 0H48', 'QMO6E54', 'QMD0H48', 'QMN1F10', 'TC01', 'TC01 (OM100 RM)');

-- Verificar tags excluídas na tabela de tags
SELECT * FROM equipamento_excluido_tag;

-- Verificar se essas tags existem nos itens importados e se tinham equipamentoSistemaId
SELECT DISTINCT equipamentoTag, equipamentoDescricao, equipamentoSistemaId 
FROM item_despesa_importado 
WHERE equipamentoTag IN ('QMD 0H48', 'QMO6E54', 'QMD0H48', 'QMN1F10', 'TC01', 'TC01 (OM100 RM)');

